p1e6.sql:
select dni as "Dni", apellido, nombre, fecha_nacimiento, fecha_registro_agencia, direccion, telefono
from personas
where apellido like 'G%';

p1e7.sql:
select nombre, apellido, fecha_nacimiento
from personas
where fecha_nacimiento > '1979-12-31' and fecha_nacimiento < '2001-01-01';

p1e8.sql:
select cuit, cod_cargo, fecha_solicitud, anios_experiencia, edad_minima, edad_maxima, sexo
from solicitudes_empresas
order by fecha_solicitud asc;

p1e11.sql:
select nro_contrato as "Nro Contrato", dni as "DNI", sueldo as "Salario", cuit as "CUIL"
from contratos
where sueldo > 2000 and cuit in ("30-10504876-5", "30-21098732-4");

p1e12.sql:
select cod_titulo, desc_titulo, tipo_titulo
from titulos
where desc_titulo like 'Tecnico%';

p1e13.sql:
select cuit, cod_cargo, fecha_solicitud, anios_experiencia, edad_minima, edad_maxima, sexo
from solicitudes_empresas
where sexo = "Femenino" or (fecha_solicitud > '2013-09-21' and cod_cargo = 6);
